  +
  +    expect(catalog).toHaveLength(1);
  +    expect(catalog[0]).toMatchObject({
  +      id: "openai",
  +      name: "OpenAI",
  +      type: "openai",
  +      env: ["OPENAI_API_KEY"],
  +    });
  +    expect(catalog[0]?.models).toContainEqual(
  +      expect.objectContaining({
  +        id: "gpt-fast",
  +        name: "GPT Fast",
  +        toolCall: true,
  +        modalities: { input: ["text"], output: ["text"] },
  +      }),
  +    );
  +  });
  +
  +  test("maps generic compatible providers to supported runtime types", () => {
  +    const catalog = parseModelsDevCatalog({
  +      compatible: {
  +        id: "compatible",
  +        name: "Compatible",
  +        api: "https://example.com/v1",
  +        npm: "@ai-sdk/openai-compatible",
  +        models: { "model-1": { id: "model-1" } },
  +      },
  +      anthropicCompatible: {
  +        id: "anthropic-compatible-example",
  +        name: "Anthropic Compatible",
  +        api: "https://example.com/anthropic",
  +        npm: "@ai-sdk/anthropic",
  +        models: { "model-a": { id: "model-a" } },
  +      },
  +    });
  +
  +    expect(catalog.map((provider) => provider.type)).toEqual([
  +      "anthropic-compatible",
  +      "openai-compatible",
  +    ]);
  +  });
  +
  +  test("returns an empty catalog for malformed input", () => {
  +    expect(parseModelsDevCatalog(null)).toEqual([]);
  +    expect(parseModelsDevCatalog([])).toEqual([]);
  +    expect(parseModelsDevCatalog("not-json")).toEqual([]);
  +  });
  +});
  +
  +describe("models.dev search", () => {
  +  const provider = parseModelsDevCatalog(fixture)[0]!;
  +
  +  test("searches providers by name, id, or API URL", () => {
  +    const providers = [
  +      provider,
  +      {
  +        ...provider,
  +        id: "other",
  +        name: "Other Provider",
  +        api: "https://models.other.test/v1",
  +      },
  +    ];
  +
  +    expect(searchModelsDevProviders(providers, "open")).toEqual([provider]);
  +    expect(searchModelsDevProviders(providers, "other.test")).toHaveLength(1);
  +    expect(searchModelsDevProviders(providers, "")).toEqual(providers);
  +  });
  +
  +  test("searches models by id, name, family, and description", () => {
  +    expect(searchModelsDevModels(provider.models, "reason")).toHaveLength(1);
  +    expect(searchModelsDevModels(provider.models, "general")).toHaveLength(1);
  +    expect(searchModelsDevModels(provider.models, "gpt")).toHaveLength(2);
  +    expect(searchModelsDevModels(provider.models, "")).toEqual(provider.models);
  +  });
  +});
  +
  +describe("models.dev feature filtering", () => {
  +  const models = [
  +    {
  +      id: "chat",
  +      name: "Chat",
  +      modalities: { input: ["text"], output: ["text"] },
  +    },
  +    {
  +      id: "tts",
  +      name: "TTS",
  +      modalities: { input: ["text"], output: ["audio"] },
  +    },
  +    {
  +      id: "transcribe",
  +      name: "Transcribe",
  +      modalities: { input: ["audio"], output: ["text"] },
  +    },
  +  ];
  +
  +  test("offers models matching the feature modality", () => {
  +    expect(modelsDevModelsForFeature(models, "language").map((m) => m.id)).toEqual([
  +      "chat",
  +    ]);
  +    expect(
  +      modelsDevModelsForFeature(models, "voice-narration").map((m) => m.id),
  +    ).toEqual(["tts"]);
  +    expect(
  +      modelsDevModelsForFeature(models, "voice-transcription").map((m) => m.id),
  +    ).toEqual(["transcribe"]);
  +  });
  +
  +  test("keeps sparse catalogs usable when no modality metadata matches", () => {
  +    const sparse = [{ id: "unknown", name: "Unknown" }];
  +    expect(modelsDevModelsForFeature(sparse, "language")).toEqual(sparse);
  +  });
  +});
  +
  +describe("models.dev provider matching", () => {
  +  const catalog = parseModelsDevCatalog({
  +    openai: {
  +      id: "openai",
  +      name: "OpenAI",
  +      npm: "@ai-sdk/openai",
  +      models: { gpt: { id: "gpt" } },
  +    },
  +    compatible: {
  +      id: "compatible",
  +      name: "Compatible",
  +      api: "https://example.com/v1/",
  +      npm: "@ai-sdk/openai-compatible",
  +      models: { model: { id: "model" } },
  +    },
  +  });
  +
  +  test("prefers an explicitly saved models.dev id", () => {
  +    expect(
  +      findModelsDevProvider(catalog, {
  +        modelsDevId: "compatible",
  +        type: "openai",
  +      })?.id,
  +    ).toBe("compatible");
  +  });
  +
  +  test("matches legacy configured providers by normalized API URL", () => {
  +    expect(
  +      findModelsDevProvider(catalog, {
  +        type: "openai-compatible",
  +        baseUrl: "https://example.com/v1",
  +      })?.id,
  +    ).toBe("compatible");
  +  });
  +
  +  test("matches canonical first-party providers by runtime type", () => {
  +    expect(findModelsDevProvider(catalog, { type: "openai" })?.id).toBe(
  +      "openai",
  +    );
  +  });
  +
  +  test("does not mislabel incompatible provider adapters", () => {
  +    expect(findModelsDevProvider(catalog, { type: "minimax" })).toBeUndefined();
  +  });
  +});

  diff --git a/src/utils/models-dev.ts b/src/utils/models-dev.ts
  new file mode 100644
  index 0000000..fa04d81
  --- /dev/null
  +++ b/src/utils/models-dev.ts
  @@ -0,0 +1,237 @@
  +import type { AiProviderType } from "../types";
  +
  +export const MODELS_DEV_CATALOG_URL = "https://models.dev/api.json";
  +
  +export interface ModelsDevModel {
  +  id: string;
  +  name: string;
  +  description?: string;
  +  family?: string;
  +  reasoning?: boolean;
  +  toolCall?: boolean;
  +  modalities?: {
  +    input: string[];
  +    output: string[];
  +  };
  +  releaseDate?: string;
  +  lastUpdated?: string;
  +}
  +
  +export interface ModelsDevProvider {
  +  id: string;
  +  name: string;
  +  api?: string;
  +  npm?: string;
  +  env: string[];
  +  type: AiProviderType;
  +  models: ModelsDevModel[];
  +}
  +
  +interface RawModelsDevModel {
  +  id?: string;
  +  name?: string;
  +  description?: string;
  +  family?: string;
  +  reasoning?: boolean;
  +  tool_call?: boolean;
  +  modalities?: {
  +    input?: string[];
  +    output?: string[];
  +  };
  +  release_date?: string;
  +  last_updated?: string;
  +}
  +
  +interface RawModelsDevProvider {
  +  id?: string;
  +  name?: string;
  +  api?: string;
  +  npm?: string;
  +  env?: string[];
  +  models?: Record<string, RawModelsDevModel>;
  +}
  +
  +const SUPPORTED_NPM_PACKAGES = new Set([
  +  "@ai-sdk/openai",
  +  "@ai-sdk/anthropic",
  +  "@ai-sdk/google",
  +  "@ai-sdk/openai-compatible",
  +  "@openrouter/ai-sdk-provider",
  +]);
  +
  +function providerType(provider: RawModelsDevProvider): AiProviderType | null {
  +  switch (provider.id) {
  +    case "openai":
  +      return "openai";
  +    case "anthropic":
  +      return "anthropic";
  +    case "google":
  +      return "google";
  +    case "openrouter":
  +      return "openrouter";
  +    case "deepseek":
  +      return "deepseek";
  +    case "zai":
  +    case "zhipuai":
  +      return "zai";
  +  }
  +  if (provider.npm === "@ai-sdk/anthropic") return "anthropic-compatible";
  +  if (
  +    provider.npm === "@ai-sdk/openai-compatible" ||
  +    provider.npm === "@openrouter/ai-sdk-provider" ||
  +    provider.npm === "@ai-sdk/openai"
  +  ) {
  +    return "openai-compatible";
  +  }
  +  return null;
  +}
  +
  +export function parseModelsDevCatalog(input: unknown): ModelsDevProvider[] {
  +  if (!input || typeof input !== "object" || Array.isArray(input)) return [];
  +
  +  const providers: ModelsDevProvider[] = [];
  +  for (const [key, raw] of Object.entries(
  +    input as Record<string, RawModelsDevProvider>,
  +  )) {
  +    if (!raw || typeof raw !== "object") continue;
  +    if (!SUPPORTED_NPM_PACKAGES.has(raw.npm ?? "")) continue;
  +    const type = providerType({ ...raw, id: raw.id ?? key });
  +    if (!type) continue;
  +
  +    const models = Object.entries(raw.models ?? {})
  +      .map(([modelKey, model]): ModelsDevModel | null => {
  +        if (!model || typeof model !== "object") return null;
  +        const id = (model.id ?? modelKey).trim();
  +        if (!id) return null;
  +        return {
  +          id,
  +          name: model.name?.trim() || id,
  +          description: model.description?.trim() || undefined,
  +          family: model.family?.trim() || undefined,
  +          reasoning: model.reasoning,
  +          toolCall: model.tool_call,
  +          modalities: model.modalities
  +            ? {
  +                input: model.modalities.input ?? [],
  +                output: model.modalities.output ?? [],
  +              }
  +            : undefined,
  +          releaseDate: model.release_date,
  +          lastUpdated: model.last_updated,
  +        };
  +      })
  +      .filter((model): model is ModelsDevModel => model !== null);
  +
  +    if (models.length === 0) continue;
  +    providers.push({
  +      id: raw.id?.trim() || key,
  +      name: raw.name?.trim() || raw.id?.trim() || key,
  +      api: raw.api?.trim() || undefined,
  +      npm: raw.npm,
  +      env: raw.env ?? [],
  +      type,
  +      models,
  +    });
  +  }
  +
  +  return providers.sort((a, b) =>
  +    a.name.localeCompare(b.name, undefined, { sensitivity: "base" }),
  +  );
  +}
  +
  +export async function loadModelsDevCatalog(): Promise<ModelsDevProvider[]> {
  +  const response = await fetch(MODELS_DEV_CATALOG_URL);
  +  if (!response.ok) {
  +    throw new Error(`models.dev catalog failed (${response.status})`);
  +  }
  +  return parseModelsDevCatalog(await response.json());
  +}
  +
  +export function searchModelsDevProviders(
  +  providers: ModelsDevProvider[],
  +  query: string,
  +): ModelsDevProvider[] {
  +  const needle = query.trim().toLowerCase();
  +  if (!needle) return providers;
  +  return providers.filter((provider) =>
  +    [provider.name, provider.id, provider.api ?? ""].some((value) =>
  +      value.toLowerCase().includes(needle),
  +    ),
  +  );
  +}
  +
  +export function searchModelsDevModels(
  +  models: ModelsDevModel[],
  +  query: string,
  +): ModelsDevModel[] {
  +  const needle = query.trim().toLowerCase();
  +  if (!needle) return models;
  +  return models.filter((model) =>
  +    [model.id, model.name, model.family ?? "", model.description ?? ""].some(
  +      (value) => value.toLowerCase().includes(needle),
  +    ),
  +  );
  +}
  +
  +export function modelsDevModelsForFeature(
  +  models: ModelsDevModel[],
  +  feature: "language" | "voice-narration" | "voice-transcription",
  +): ModelsDevModel[] {
  +  const matches = models.filter((model) => {
  +    const input = model.modalities?.input ?? [];
  +    const output = model.modalities?.output ?? [];
  +    if (feature === "voice-narration") {
  +      return input.includes("text") && output.includes("audio");
  +    }
  +    if (feature === "voice-transcription") {
  +      return input.includes("audio") && output.includes("text");
  +    }
  +    return input.includes("text") && output.includes("text");
  +  });
  +  if (matches.length > 0) return matches;
  +  // Older or sparse catalog entries may not declare modalities. Preserve
  +  // usability only when the catalog genuinely has no modality information;
  +  // do not offer image or chat models for speech merely because no TTS model
  +  // matched.
  +  return models.every((model) => !model.modalities) ? models : [];
  +}
  +
  +const CANONICAL_PROVIDER_IDS: Partial<Record<AiProviderType, string>> = {
  +  openai: "openai",
  +  anthropic: "anthropic",
  +  google: "google",
  +  deepseek: "deepseek",
  +  openrouter: "openrouter",
  +  zai: "zai",
  +};
  +
  +function normalizeUrl(value: string | undefined): string {
  +  return (value ?? "").trim().replace(/\/+$/, "").toLowerCase();
  +}
  +
  +export function findModelsDevProvider(
  +  providers: ModelsDevProvider[],
  +  config: {
  +    modelsDevId?: string;
  +    type: AiProviderType;
  +    baseUrl?: string;
  +  },
  +): ModelsDevProvider | undefined {
  +  if (config.modelsDevId) {
  +    const explicit = providers.find(
  +      (provider) => provider.id === config.modelsDevId,
  +    );
  +    if (explicit) return explicit;
  +  }
  +  const baseUrl = normalizeUrl(config.baseUrl);
  +  if (baseUrl) {
  +    const byUrl = providers.find(
  +      (provider) => normalizeUrl(provider.api) === baseUrl,
  +    );
  +    if (byUrl) return byUrl;
  +  }
  +  const canonicalId = CANONICAL_PROVIDER_IDS[config.type];
  +  return canonicalId
  +    ? providers.find((provider) => provider.id === canonicalId)
  +    : undefined;
  +}

