  +              event.preventDefault();
  +              const typed = query.value.trim();
  +              if (exact && typed) {
  +                choose(
  +                  props.models.find(
  +                    (model) =>
  +                      model.id.toLowerCase() === typed.toLowerCase(),
  +                  )?.id ?? typed,
  +                );
