function remember(key: string, url: string): void {
  cache.set(key, url);
  while (cache.size > MAX_CACHED_CLIPS) {
    const oldest = cache.keys().next().value;
    if (oldest === undefined) break;
    const stale = cache.get(oldest);
    if (stale) URL.revokeObjectURL(stale);
    cache.delete(oldest);
  }
}

