  }

  const persona = cast.find((p) => p.name.trim().toLowerCase() === name);
  if (!persona) return req;

  return {
    ...req,
    voice: req.voice ?? persona.speechVoice,
    voices: req.voices ?? persona.speechVoices,
    instructions: req.instructions ?? persona.voice,
  };
}

