 * assembly with no Node.js built-ins, and it is also imported by the
 * Vite-bundled client code in `src/utils/{ai-client,ai-orchestrator}.ts`.
 * The Node runtime is opted into at the action boundary in
 * `convex/agents.ts`, which is the only file that needs it.
 */
import type { Persona, ProjectBrief, WriterProfile } from "../src/types";
import { firstSubstantiveSentence } from "./agentTools";
import { probeSummaryLine } from "../src/utils/dossier-probes";

export type FeedbackType =
  | "encouragement"
  | "suggestion"
  | "critique"
  | "perspective";

export interface AgentPersona {
  id: string;
  name: string;
  role: string;
  description: string;
  focus: string;
  /** Short fictional history for role play and continuity. */
  backstory?: string;
  /** The editor's specific theory and method of criticism. */
  criticalMethod?: string;
  /** Rich voice spec — distinct diction/rhythm/signature for this editor. */
  voice?: string;
  /** Recurring rhetorical habits that make the editor recognizable. */
  signatureMoves?: string[];
  /** Language and behaviors this editor must not borrow from the others. */
  avoidances?: string[];
  /** A few sample lines in this persona's voice, used as light few-shot. */
  sampleLines?: string[];
  /** Optional per-persona generation prefs (honored on the BYOK client path). */
  providerId?: string;
  model?: string;
  temperature?: number;
  /** Optional colour from the persona object; not used by the LLM prompt. */
  color?: string;
  icon?: string;
}

export interface AgentRequest {
  persona: AgentPersona;
  brief: ProjectBrief | null;
  draftText: string;
  /** Private writer context, kept separate from the folio's project brief. */
  writerProfile?: WriterProfile;
  /** Anchor sentence the note should pin to, if known. */
  anchor?: string;
  /** Prior conversation for follow-up turns. */
  priorMessages?: Array<{ author: "user" | "persona"; text: string }>;
  /** The user's follow-up question, if this is a reply. */
  userMessage?: string;
  /**
   * Prose summary of how the draft has been moving — paragraphs added and
   * cut, net words, the most recent new material. Lets an editor respond to
   * the writer's direction rather than to a cold snapshot.
   */
  trajectory?: string;
  /**
   * The passages written since this editor last read. When present the note
   * should be aimed here, with the full draft as context rather than subject.
   */
  newMaterial?: string;
  /** Direct instruction the user is asking the persona to act on. */
  instruction?:
    | "feedback"
    | "elaborate"
    | "riff"
    | "rewrite-suggestion"
    | "analyze";
}

export interface AgentResponse {
  text: string;
  type: FeedbackType;
  provider: "rivet" | "anthropic" | "openai" | "portkey" | "local";
  /** Soft signal of how confident the model is in the answer (0-1). */
  confidence?: number;
  /**
   * Exact draft passage the note pins to. Populated from the `quote_passage`
  switch (p.id) {
    case "devil":
      return "critique";
    case "angel":
      return "encouragement";
    case "scholar":
    case "editor":
      return "suggestion";
    case "reader":
    default:
      return "perspective";
  }
}

